#include <iostream>
#include <cctype>

int main() {
    std::cout << "Enter a hex digit: ";
    char hexDigit{};
    if (std::cin >> hexDigit) {
        char upperDigit = static_cast<char>(std::toupper(static_cast<unsigned char>(hexDigit)));

        if (upperDigit >= 'A' && upperDigit <= 'F') {
            int decimalValue = 10 + (upperDigit - 'A');
            std::cout << "The decimal value for hex digit " << upperDigit << " is " << decimalValue << "\n";
        } else if (std::isdigit(static_cast<unsigned char>(upperDigit))) {
            int decimalValue = upperDigit - '0';
            std::cout << "The decimal value for hex digit " << upperDigit << " is " << decimalValue << "\n";
        } else {
            std::cout << hexDigit << " is an invalid input\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string message = "ABCD";
    std::cout << "Length: " << message.length() << "\n";
    std::cout << "First char via at: " << message.at(0) << "\n";

    // Modify in-place using subscript operator
    message[0] = 'P';
    std::cout << "Modified first char: " << message[0] << "\n";
    std::cout << "Full modified string: " << message << "\n";

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string s1 = "ABC";
    std::string s2 = "ABE";

    // Concatenation using + and +=
    std::string prefix = "Item: ";
    std::string combined = prefix + s1 + " and " + s2;
    combined += '!';
    std::cout << combined << "\n";

    // Lexicographical comparisons
    std::cout << (s1 == s2) << "\n";
    std::cout << (s1 != s2) << "\n";
    std::cout << (s1 < s2) << "\n";
    std::cout << (s1 > s2) << "\n";

    return 0;
}
